(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["da"] = {"ui":{"skip":"Spring til indhold","back":"← Tilbage til AI-gile","lang.button":"Sprog: {name}","lang.dialog":"Vælg et sprog","lang.search":"Søg efter sprog","lang.none":"Intet sprog passer","lang.notYet":"{name} er ikke oversat endnu","theme.aria":"Skift mellem lyst og mørkt tema","theme.toLight":"Skift til lyst tema","theme.toDark":"Skift til mørkt tema","index.title":"AI-gile: dit AI-udviklerteam på ét board","index.description":"AI-gile er et kanban-board til AI-kodeteams. De arbejder, mens du sover; du får én kort bunke ting at beslutte, teste og godkende.","hero.logoAlt":"AI-gile board-ikon","hero.h1.html":"Dit AI-udviklerteam på ét&nbsp;board.","hero.alpha":"🐣 Lukket pre-alfa","hero.alphaTitle":"Tidligt og ufærdigt: tak, fordi du prøver det!","hero.lede":"De bygger, mens du sover. Du vågner op til én kort bunke: et par spørgsmål, et par ting at teste, en lilla diamant eller to. Klik, godkend, tilbage til din kaffe.","dl.windows":"Windows-app","dl.browser":"Kør det i din browser","dl.soon":"Kommer snart","dl.notify":"🔔 Giv mig besked, når det åbner","dl.notifySmall":"Alfa eller beta","hero.secondary":"Agile, men teamet har aldrig brug for en stand-up-kaffe. (De holder stand-ups alligevel.)","pitch.h2":"AI-gile på lige så mange ord, som du vil","pitch.lede":"Vælg en længde, fra ét ord til 144. Hver længde er sin egen beskrivelse, skrevet til netop den størrelse. Træk i skyderen eller brug piletasterne.","pitch.rangeLabel":"Længde i ord","pitch.dice":"🎲 en anden version","pitch.words.one":"{n} ord","pitch.words.other":"{n} ord","pitch.letters.one":"{n} bogstav","pitch.letters.other":"{n} bogstaver","pitch.chars.one":"{n} tegn","pitch.chars.other":"{n} tegn","count.line.html.one":"{n} kort på boardet lige nu","count.line.html.other":"{n} kort på boardet lige nu","features.aria":"Hvad det kan","f.pile.h":"Én bunke til dig","f.pile.html":"<b>Til dig</b> samler alt, der venter på dig, på tværs af alle projekter: spørgsmål, ting at teste, opgaver kun et menneske kan løse. Din kø fortæller, hvad der er næste skridt, og hvor lang tid det tager.","f.sleep.h":"Teams, der arbejder, mens du sover","f.sleep.p":"Hvert projekt har en lead og et team af AI-agenter. Skriv en kommentar på et kort, så vågner teamet, gør arbejdet og afleverer det tilbage med trin, som et træt menneske kan følge.","f.tester.h":"En AI-tester tjekker først","f.tester.p":"Før noget når frem til dig, følger en tester trinene i en kopi af appen og viser, hvad den så, med et skærmbillede. Bladr igennem de bestårede og godkend med ét klik.","f.proof.h":"Bevis, ikke løfter","f.proof.p":"Hver aflevering viser, hvad der er ændret: filerne, forskellene, skærmbillederne. Du behøver ikke åbne hver app for at se, om det er færdigt.","f.chat.h":"Chat med dine leads","f.chat.p":"En Discord-agtig bjælke: ét ikon pr. projekt, lilla diamanter ved det, der skal bruge dig. Skriv en idé til en lead; så laver de den om til kort og en plan, med en ✅ Go-knap.","f.tidy.h":"Holder selv orden","f.tidy.p":"Beslægtede kort smelter sammen, rodede titler bliver rettet, og et token-tjek holder koden slank. Færre ting at skifte mellem, mindre at tænke på.","f.private.h":"Dit, på din computer","f.private.li1":"Boardet kører på din egen maskine og svarer kun dig.","f.private.li2":"Private beskeder mellem mennesker er end-to-end-krypterede.","f.private.li3":"Ingen konti, ingen trackere, ingen cookies.","f.lang.h":"På dit sprog","f.lang.p":"Over 120 sprog, fra hollandsk, walisisk og japansk til pirat, Yoda og klingon, med et hurtigt skift tilbage til engelsk til udviklerordene.","tl.aria":"Tidslinje fra den første samtale til køreplanen","tl.h2":"Fra den første chat til det, der kommer","tl.lede":"Rigtige datoer og tidspunkter i din egen tidszone. Efter i dag er det planen, uden lovede datoer.","tl.today":"I dag","tl.planned":"planlagt","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Vær med","join.lede":"AI-gile bygges af et lille menneske og et stort antal tålmodige agenter. Det er privat for nu, i en lukket alfa med venner. Vil du prøve det, når det åbner?","join.btn":"Meld interesse","join.small":"Vi sender dig en mail, ikke andet","footer.tag":"AI-gile. Ingen trackere, ingen cookies, ingen stand-up-kaffe.","footer.licence":"Erhvervslicens","footer.status":"Status","form.sending":"Sender…","form.failed":"Det virkede ikke: prøv igen senere.","form.offline":"Kunne ikke nå AI-gile: prøv igen senere.","interest.title":"AI-gile: sig til, når alfaen åbner","interest.description":"Skriv din mail, så får du besked, når AI-giles lukkede alfa eller beta åbner.","interest.h1":"🔔 Giv mig besked, når det åbner","interest.lede":"AI-gile er i lukket pre-alfa. Skriv din mail, så skriver vi én gang, når der er en plads til dig.","interest.email":"Din mail","interest.which":"Hvilken test?","interest.alpha":"Lukket alfa: tidligt, groft, mange ændringer","interest.beta":"Beta: mere stabil, senere","interest.both":"Begge dele, hvad der kommer først","interest.submit":"Sæt mig på listen","interest.thanks":"Tak! Du er på listen.","interest.kept":"Kun din mail og den test, du valgte, gemmes, kun til denne liste. Intet nyhedsbrev, ingen trackere.","licence.title":"AI-gile: erhvervslicens","licence.description":"Bruger du AI-gile i din virksomhed? Ansøg om en gratis erhvervslicens.","licence.h1":"📜 Erhvervslicens","licence.lede":"Bruger du AI-gile på arbejde? Fortæl os, hvem du er, og hvad du laver. Gør det noget godt, er licensen gratis.","licence.company":"Virksomhed","licence.website":"Hjemmeside","licence.what":"Hvad du laver","licence.how":"Hvordan det hjælper verden","licence.email":"Mail","licence.submit":"Ansøg","licence.thanks":"Tak! Vi svarer på mail.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Alt er roligt","status.checking":"Tjekker…","status.offline":"Kan ikke nå statustjenesten lige nu (prøver igen)","status.updated":"opdateret {ago}","status.justNow":"lige nu","status.min":"{n} min siden","status.hours":"{n} t siden","status.days":"{n} d siden","live.h2":"Se det blive bygget, live","live.caption":"Hvert kort er skjult: du ser arbejdets form, ikke ordene.","live.watching.one":"live: {n} kigger med","live.watching.other":"live: {n} kigger med","live.offline":"Live-tavlen holder en lille pause. Kig forbi igen snart.","live.cols":"Backlog|To do|I gang|Teamet tjekker|Til dig at teste|Til teamet|Færdig","live.last.now":"Sidste kort flyttet lige nu","live.last.min.one":"Sidste kort flyttet for {n} min. siden","live.last.min.other":"Sidste kort flyttet for {n} min. siden","live.last.hour.one":"Sidste kort flyttet for {n} time siden","live.last.hour.other":"Sidste kort flyttet for {n} timer siden","live.last.day.one":"Sidste kort flyttet for {n} dag siden","live.last.day.other":"Sidste kort flyttet for {n} dage siden"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotter.","Uddelegeret."]},{"n":2,"texts":["Robotternes kanban.","Agenter, organiseret.","Idéer, bygget."]},{"n":3,"texts":["Kanban for robotter.","Idéer bliver til funktioner.","Gratis agent-kanban."]},{"n":5,"texts":["Kanban-board drevet af AI-agenter.","Du skriver kort. Agenter bygger.","Gratis, lokalt, testet, lidt fjollet."]},{"n":8,"texts":["Et gratis kanban-board, hvor AI-agenter gør arbejdet.","Skriv en idé. Agenter bygger den. Du godkender.","Agile til ét menneske og mange tålmodige robotter."]},{"n":13,"texts":["Et kanban-board på din computer, hvor AI-agenter tager kortene op.","Skriv en idé. Et team af agenter bygger den. En tester tjekker den.","Gratis, ingen konti, ingen trackere: et board, nogle robotter og dig som chef."]},{"n":21,"texts":["AI-gile er et kanban-board til arbejde med AI-kodeagenter. De tager kortene op; du tester og godkender dem.","Hvert projekt får en lead og et team af AI-agenter. Skriv en kommentar på et hvilket som helst kort, så går teamet i gang.","Et gratis, personligt to do-board, der kører på din egen computer. Arbejderne er robotter. Den, der siger ja, er dig."]},{"n":34,"texts":["Du lægger idéer på et board. Et team af AI-agenter gør dem til virkende funktioner, tester dem og afleverer dem tilbage med trin, du kan prøve. Intet tæller som færdigt, før du siger det.","AI-gile er et hjemmelavet kanban-board, som Rich har bygget med masser af hjælp fra de agenter, det nu styrer. Det er gratis, kører på din computer og deles med venner, ikke solgt.","Forestil dig et helt almindeligt kanban-board med kolonner fra Backlog til Færdig, bortset fra at kortene bliver taget op af AI-agenter. De melder fremskridt, spørger, når de sidder fast, og venter altid på din tommelfinger op."]},{"n":55,"texts":["AI-gile er et kanban-board, hvor teamet består af AI-agenter. Hvert projekt har en lead, der planlægger arbejdet, og hjælpere, der bygger det. Når en funktion er klar, prøver en AI-tester den og tager et skærmbillede, og så lander den i din bunke. Godkend den, eller skriv en kommentar, så laver de den om.","Det startede som én persons måde at holde styr på mange AI-kodesessioner på én gang og voksede til et rigtigt board. Det kører på din maskine, kræver ingen konto og har ingen trackere. Det er gratis for venner og nysgerrige. Det er også ufærdigt, så regn med ru kanter og en overraskelse nu og da.","Her er den ærlige version. Du skal stadig selv have idéerne, og du skal stadig selv tjekke resultaterne. AI-gile klarer alt derimellem: det holder kortene i orden, vækker den rigtige agent, når du skriver en kommentar, viser præcis, hvad der er ændret, og samler det hele i én kort bunke til dig."]},{"n":89,"texts":["AI-gile er et gratis kanban-board, som du kører på din egen computer. I stedet for mennesker har hvert projekt et team af AI-agenter: en lead, der gør dine idéer til kort og en plan, og hjælpere, der tager kortene op i prioriteret rækkefølge. Når noget er bygget, følger en AI-tester testtrinene og viser dig, hvad den så. Derefter venter det i én bunke, der hedder Til dig. Du godkender det, eller du skriver en kommentar, og teamet prøver igen. Intet når nogensinde til Færdig uden dig.","Nogle ting, du måske ikke venter. En nattevagt holder To do-kolonnen fyldt op, mens du sover, og vælger kort, der ikke kræver svar fra dig. En token-tæller viser, hvor meget agenterne har brugt i dag og i denne uge, og No Token Mode siger til dem, at de skal holde op med at bruge. Du kan skrive til venner, og private beskeder er end-to-end-krypterede. Boardet taler omkring 120 sprog, blandt andet hollandsk, flamsk, pirat og klingon. Intet af det koster en krone, og ingen prøver at sælge dig det.","AI-gile er et lille, personligt projekt, ikke en virksomhed. Rich ville passe flere AI-kodeprojekter uden at åbne hver eneste app for at tjekke dem, så han og agenterne byggede et board til det og brugte derefter boardet til at bygge resten af sig selv. Det er i lukket pre-alfa, hvilket betyder, at det virker, stort set, for en lille håndfuld venner. Der er ingen prisside, intet nyhedsbrev og ingen vækstplan. Lyder det nyttigt, kan du bede om at prøve det, når det åbner lidt mere op."]},{"n":144,"texts":["AI-gile er et kanban-board til ét menneske og en masse AI-agenter. Det kører på din egen computer, og det er helt gratis. Du tilføjer projekter, og hvert projekt får en lead og et lille team. Du chatter med leaden, lidt ligesom på Discord, og beskriver en idé; leaden gør den til kort og en plan og venter så på, at du trykker Go. Teamet arbejder kortene igennem i prioriteret rækkefølge ved hjælp af en enkel kommandolinje, lavet til sprogmodeller. Før noget kommer tilbage til dig, følger en AI-tester trinene i en kopi af appen og vedhæfter et skærmbillede. Færdigt arbejde lander i din bunke med de ændrede filer og forskellen. Du godkender det, eller du skriver en kommentar, og teamet vågner og prøver igen. Kun du kan flytte et kort til Færdig. Der er ingen konti, ingen trackere og ingen cookies, og det hele bliver på din egen computer.","En dag med AI-gile, cirka. Om aftenen skriver du et par kommentarer: denne knap sidder det forkerte sted, den liste burde være sorteret, kunne vi få en mørk tilstand. Du går i seng. Agenterne læser kommentarerne, laver ændringerne, tester dem og afleverer dem tilbage til dig. Hvis To do løber tør, fylder nattevagten den op fra backloggen med kort, der ikke kræver svar fra dig. Om morgenen ligger der én kort bunke: et par spørgsmål og et par ting at prøve, hver med trin, som en søvnig person kan følge, og et skærmbillede af, at det virker. Du klikker dig igennem, godkender de gode og sender resten tilbage. En token-tæller viser, hvad det hele brugte, og No Token Mode er der til de magre uger. Så spiser du morgenmad, som agenterne endnu ikke kan hjælpe med.","Først, hvad AI-gile ikke er. Det er ikke en startup, det er ikke til salg, og ingen indsamler dine data. Det er et gratis board, der kører på din computer, uden konti, uden trackere og uden cookies. Hvad det er: ét ryddeligt sted, hvor du kan se alle dine AI-kodeprojekter på én gang, med et team af agenter, der tager kortene, og dig, der træffer beslutningerne. Det slår beslægtede kort sammen, retter rodede titler og holder øje med, hvor slank koden bliver. Det taler omkring 120 sprog, fra hollandsk og flamsk til pirat og klingon. Venner kan skrive til hinanden, privat og krypteret. Det er bygget af Rich og et stort antal tålmodige agenter, mest ved at bruge sig selv. Det er i lukket pre-alfa, så det er groft nogle steder. Lyder det som sjov, så spørg pænt, og måske kommer du tidligt med."]}],"quips":{"1":"Ét ord. Dristigt. Måske for dristigt.","3":"Tre ord. Allerede mere ærligt end de fleste produktsider.","8":"Otte ord. Stadig kortere end et stand-up.","21":"Længderne er i øvrigt story points. Selvfølgelig er de det.","55":"Femoghalvtreds ord. To kort blev færdige, mens du læste det.","144":"Det var den lange. Der er ingen 233. Agenterne er gået i seng."}},"timeline":{"first-idea.name":"Den første idé","first-idea.line":"Den allerførste samtale, før der fandtes nogen kode.","first-board.name":"Første board","first-board.line":"Et board, der følger sin egen opbygning: kort, kolonner, træk og slip, projekter.","team-roles.name":"Team og roller","team-roles.line":"Agentprofiler, teamskabeloner, rum og hvem der gør hvad.","install.name":"Installation og udgivelser","install.line":"En zip, en ven kan installere, selvopdatering, kanaler og tilbagerulning.","usage-saver.name":"Forbrugsbesparelse","usage-saver.line":"Mål, hvad kørsler koster, hold koden slank, spar på din grænse.","friends.name":"Venner og deling","friends.line":"Private beskeder, et krypteret relæ, invitationer, roller og delte projekter.","languages.name":"Sprog","languages.line":"Hver skærmtekst i en sprogfil, med hollandsk og flamsk først.","ai-tester.name":"AI-tester","ai-tester.line":"En tester tjekker hver aflevering først og viser, hvad den så.","website.name":"Hjemmesiden","website.line":"aigile.lol, teaseren og denne tidslinje.","streaming.name":"Chat og streaming","streaming.line":"Discord, Twitch, OBS, streamertilstand, GIF'er og emojis.","no-ai.name":"Udgaven uden AI","no-ai.line":"Et board til folk, der koder uden AI, og offentlige boards.","night-watch.name":"Nattevagt","night-watch.line":"En vagtmand og en Scrum Master holder teamene på sporet, mens du sover.","p-more.name":"Alt det andet","p-more.line":"Mindre idéer, der stadig venter på deres tur.","p-android.name":"Telefon og Android","p-android.line":"Nå dit board fra en telefon, og så en indbygget Android-app.","p-release.name":"Alfa og videre","p-release.line":"Lukket alfa, den levende hjemmeside, så beta.","p-languages.name":"Flere sprog","p-languages.line":"Mere end hundrede sprog og en fordybelsestilstand til sprogelever.","p-engines.name":"Flere AI-motorer","p-engines.line":"Vælg Claude, Codex eller Gemini pr. agent.","p-pro.name":"Professionel praksis","p-pro.line":"Risikomærker, merge-porte, hændelseskort og autoværn.","p-self.name":"At passe på dig","p-self.line":"Træt-tilstand, påmindelser om selvomsorg og 4:20.","p-servers.name":"Servere og vækst","p-servers.line":"Globale serverindstillinger, roller og planlægning for vækst.","p-livestream.name":"Streaming-ekstra","p-livestream.line":"Twitch-chat, egne emojis og en offentlig live-visning."},"words":{"button":"📖 Udviklerord","h":"📖 Udviklerord forklaret","intro":"De ord, udviklere (og AI-teamene) bruger, på almindeligt dansk.","search":"Søg efter et ord…","none":"Intet ord passer.","close":"Luk","list":[{"id":"backlog","word":"Backlog","text":"Idéer og arbejde, der endnu ikke er planlagt. Der bliver ikke arbejdet på noget, før det flyttes til To do."},{"id":"sprint","word":"Sprint","text":"En kort arbejdsperiode (ofte en uge eller to) med et aftalt sæt kort, der skal blive færdige.","also":["sprints","sprint"]},{"id":"standup","word":"Stand-up","text":"En hurtig status: hvad hvert teammedlem har lavet, hvad de gør nu, og hvad der står i vejen.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Noget, der ikke virker, som det skal.","also":["bugs","fejl"]},{"id":"test","word":"Test","text":"At prøve et færdigt stykke arbejde for at tjekke, at det gør det, der blev bedt om, før du godkender det.","also":["tests","teste"],"noTip":1},{"id":"commit","word":"Commit","text":"Et gemt øjebliksbillede af koden med en kort note om, hvad der er ændret. Du kan altid gå tilbage til et.","also":["commits"]},{"id":"push","word":"Push","text":"At sende gemte øjebliksbilleder (commits) fra denne computer op til GitHub, så de er sikkerhedskopieret og delt."},{"id":"branch","word":"Branch","text":"En separat arbejdslinje i koden, så man kan lave ændringer uden at røre hovedversionen.","also":["branches","gren"]},{"id":"merge","word":"Merge","text":"At føje en branchs ændringer tilbage til hovedversionen."},{"id":"repo","word":"Repo","text":"Projektets mappe med kode og hele historikken af commits, som oftest også gemt på GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"At rydde op i koden uden at ændre, hvad den gør: mindre filer, tydeligere navne, mindre gentagelse."},{"id":"deploy","word":"Deploy","text":"At sætte en ny version i luften, fx på en server, hvor folk bruger den."},{"id":"kanban","word":"Kanban","text":"Et board med kolonner (To do, I gang, Færdig), hvor kortene flytter sig fra venstre mod højre, efterhånden som arbejdet skrider frem."},{"id":"wip","word":"WIP-grænse","text":"Work in progress: det højeste antal kort, en kolonne bør rumme, så teamet gør ting færdige, før det starter flere.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"At bede om, at en branchs ændringer bliver tjekket og flettet ind i hovedversionen.","also":["PR"]},{"id":"hook","word":"Hook","text":"En lille kommando, der kører af sig selv på et bestemt tidspunkt, fx når en AI-session starter, så teamet hører dine kommentarer.","also":["hooks"]},{"id":"token","word":"Token","text":"Den enhed, AI-forbrug måles i: groft sagt nogle få bogstaver tekst, der læses eller skrives. Færre tokens, mere tilbage af dit abonnement.","also":["tokens"]},{"id":"agent","word":"Agent","text":"En AI, der arbejder selvstændigt på en opgave: læser koden, laver ændringer, kører tjek og melder tilbage.","also":["agenter","agents"]}]}};
